"""Build a readable HTML overview from the JUnit XML generated by Pytest."""

from __future__ import annotations

import argparse
import html
import xml.etree.ElementTree as ET
from pathlib import Path


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("junit", type=Path, help="Pytest JUnit XML file")
    parser.add_argument("output", type=Path, help="HTML report path")
    args = parser.parse_args()

    root = ET.parse(args.junit).getroot()
    cases = list(root.iter("testcase"))
    passed = sum(case.find("failure") is None and case.find("error") is None and case.find("skipped") is None for case in cases)
    failed = sum(case.find("failure") is not None or case.find("error") is not None for case in cases)
    skipped = sum(case.find("skipped") is not None for case in cases)

    groups: dict[str, list[ET.Element]] = {}
    for case in cases:
        group = "Selenium · браузерные сценарии" if ".e2e." in case.get("classname", "") else "Pytest · серверные и интеграционные сценарии"
        groups.setdefault(group, []).append(case)

    rows = []
    for group, items in groups.items():
        rows.append(f"<h2>{html.escape(group)}</h2><ol>")
        for case in items:
            failed_case = case.find("failure") is not None or case.find("error") is not None
            skipped_case = case.find("skipped") is not None
            status = "Ошибка" if failed_case else "Пропущен" if skipped_case else "Пройден"
            css = "fail" if failed_case else "skip" if skipped_case else "pass"
            label = html.escape(case.get("name", "тест"))
            seconds = float(case.get("time", "0"))
            rows.append(f'<li><span class="pill {css}">{status}</span><code>{label}</code><small>{seconds:.2f} с</small></li>')
        rows.append("</ol>")

    report = f"""<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Отчёт Pytest и Selenium</title><style>
*{{box-sizing:border-box}}body{{margin:0;padding:42px;background:#f3f6fc;color:#101b3b;font:16px/1.5 Segoe UI,Arial,sans-serif}}
main{{max-width:1100px;margin:auto;background:white;border:1px solid #dfe6f1;border-radius:24px;padding:38px;box-shadow:0 18px 50px #19265a12}}
.eyebrow{{color:#3943b7;text-transform:uppercase;letter-spacing:.14em;font-weight:700;font-size:13px}}h1{{font-size:34px;margin:8px 0}}.sub{{color:#62708b;margin:0 0 28px}}
.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:24px 0 32px}}.stat{{background:#f3f6fc;padding:18px;border-radius:16px}}.stat strong{{display:block;font-size:29px;color:#150578}}.stat span{{font-size:13px;color:#62708b}}
h2{{font-size:18px;margin:30px 0 10px}}ol{{padding:0;margin:0;list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:9px}}li{{display:flex;align-items:center;gap:10px;background:#fafbfe;padding:10px 12px;border-radius:10px;min-width:0}}code{{font:12px/1.4 Consolas,monospace;overflow-wrap:anywhere;flex:1}}small{{color:#71809b;white-space:nowrap}}.pill{{padding:3px 8px;border-radius:999px;font-size:11px;font-weight:700}}.pass{{background:#dff6eb;color:#14754b}}.fail{{background:#ffe8e7;color:#b42318}}.skip{{background:#fff2d6;color:#8a5b00}}footer{{margin-top:28px;color:#74819a;font-size:12px}}
@media(max-width:700px){{body{{padding:16px}}main{{padding:22px}}.stats{{grid-template-columns:1fr 1fr}}ol{{grid-template-columns:1fr}}h1{{font-size:26px}}}}
</style><main><div class="eyebrow">Автоматизированная проверка · Selenium + Pytest</div><h1>Результаты контрольного прогона</h1><p class="sub">Сформировано из JUnit XML: {html.escape(args.junit.name)}</p>
<section class="stats"><div class="stat"><strong>{len(cases)}</strong><span>всего проверок</span></div><div class="stat"><strong>{passed}</strong><span>пройдено</span></div><div class="stat"><strong>{failed}</strong><span>ошибок</span></div><div class="stat"><strong>{skipped}</strong><span>пропущено</span></div></section>
{''.join(rows)}<footer>Источник чисел и статусов — JUnit XML, созданный pytest --junitxml. Снимок страницы сохранён Selenium.</footer></main></html>"""
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(report, encoding="utf-8")
    print(f"Отчёт сохранён: {args.output} ({passed}/{len(cases)} пройдено, {failed} ошибок)")


if __name__ == "__main__":
    main()
